class Solution:
    def numberOfSequence(self, n: int, sick: List[int]) -> int:
        MOD = 10**9 + 7

        def count_ways(left, right):
            if left > right:
                return 1
            if left == right:
                return 2
            return (count_ways(left + 1, right) + count_ways(left, right - 1)) % MOD

        sick.sort()
        total_ways = 1
        prev = -1

        for i in range(len(sick)):
            if i > 0 and sick[i] == sick[i - 1] + 1:
                continue
            if prev != -1 and sick[i] == prev + 2:
                total_ways = (total_ways * 2) % MOD
            else:
                left = sick[i] - prev - 1
                right = sick[i] - prev - 1
                total_ways = (total_ways * count_ways(0, left - 1)) % MOD
            prev = sick[i]

        if prev != n - 1:
            total_ways = (total_ways * count_ways(0, n - prev - 2)) % MOD

        return total_ways
